//! Conformance suite for the `network` module.
//!
//! The six invariants of `docs/PLAN.md` §2.3 are generated by
//! `detent_core::module_conformance!`; this file supplies the fixtures, the
//! model strategy and the injection probes it needs, and asserts that each
//! fixture parses to the exact model it should.
//!
//! `fixtures/network/systemd-261/10-eth0.network` is the stock
//! `systemd-networkd` `.network` shape at systemd 261.3 (sections `[Match]`,
//! `[Network]`, `[Address]`, `[Route]`, `[VLAN]`; `DHCP`, `Address`, `Gateway`,
//! `DNS`, `Destination`, `Id`); the file is verbatim from
//! `man systemd.network`'s example at that tag, trimmed to the modeled subset.
//! `fixtures/network/network-manager-1.52/eth0.nmconnection` is a minimal
//! `NetworkManager` keyfile at `NetworkManager` 1.52
//! (`[connection]`/`[ethernet]`/`[ipv4]`/`[ipv6]`); verbatim from
//! `nm-settings-keyfile(5)` at that tag.
//! `fixtures/network/ifupdown-0.8/interfaces` is Debian's stock
//! `/etc/network/interfaces` at ifupdown 0.8 (stanzas `auto`/`iface` plus
//! `source-directory interfaces.d`); verbatim from the Debian `ifupdown`
//! package at that version.
//! `fixtures/network/netplan-1.1/netplan.yaml` is the stock netplan YAML at
//! netplan 1.1 (`network.ethernets.eth0.{dhcp4,addresses,gateway4,nameservers,routes}`);
//! verbatim from `netplan.io`'s example at that tag.
//! `fixtures/network/edge/` holds hand-made adversarial cases (CRLF, no
//! trailing newline, tabs, unknown sections/keys per backend, YAML
//! comments/anchors left opaque).

use detent_core::descriptor::{HostProfile, ValidationCtx};
use detent_core::module::ConfigModule;
use detent_module_network::{Interface, Model, NetworkModule, Route, Vlan};
use proptest::prelude::{Just, Strategy, prop_oneof};

/// `systemd-networkd` stock `.network` at systemd 261.3.
const SYSTEMD: &str = include_str!("../../../../fixtures/network/systemd-261/10-eth0.network");
/// `NetworkManager` keyfile at `NetworkManager` 1.52.
const NM: &str =
    include_str!("../../../../fixtures/network/network-manager-1.52/eth0.nmconnection");
/// `ifupdown` stock interfaces at ifupdown 0.8.
const IFUPDOWN: &str = include_str!("../../../../fixtures/network/ifupdown-0.8/interfaces");
/// netplan YAML at netplan 1.1.
const NETPLAN: &str = include_str!("../../../../fixtures/network/netplan-1.1/netplan.yaml");
/// Every line terminated with `\r\n`.
const CRLF: &str = include_str!("../../../../fixtures/network/edge/crlf.network");
/// A file whose last line has no terminator.
const NO_NEWLINE: &str =
    include_str!("../../../../fixtures/network/edge/no-trailing-newline.network");
/// Tabs between key and value.
const TABS: &str = include_str!("../../../../fixtures/network/edge/tabs-and-spacing.network");
/// Unknown sections and keys (per-backend) plus YAML anchors/comments left opaque.
const UNKNOWN: &str = include_str!("../../../../fixtures/network/edge/unknown-sections.network");

fn cidr_strategy() -> impl Strategy<Value = String> {
    prop_oneof![
        Just("192.168.1.10/24".to_owned()),
        Just("10.0.0.5/8".to_owned()),
        Just("172.16.0.1/16".to_owned()),
        Just("2001:db8::1/64".to_owned()),
        Just("fd00::1/64".to_owned()),
    ]
}

fn ip_strategy() -> impl Strategy<Value = String> {
    prop_oneof![ip_v4_strategy(), ip_v6_strategy()]
}

fn ip_v4_strategy() -> impl Strategy<Value = String> {
    prop_oneof![
        Just("192.168.1.1".to_owned()),
        Just("8.8.8.8".to_owned()),
        Just("10.0.0.1".to_owned()),
    ]
}

fn ip_v6_strategy() -> impl Strategy<Value = String> {
    // `2001:db8::1` — must contain `:` so a gateway parses back into the
    // same family it was rendered from (invariant 3).
    Just("2001:db8::1".to_owned())
}

fn iface_name_strategy() -> impl Strategy<Value = String> {
    prop_oneof![
        Just("eth0".to_owned()),
        Just("eth1".to_owned()),
        Just("ens3".to_owned()),
        Just("wlan0".to_owned()),
    ]
}

/// A static route whose `via` is in the same family as its `to`.
fn route_strategy() -> impl Strategy<Value = Route> {
    cidr_strategy().prop_flat_map(|to| {
        let via = if to.contains(':') {
            ip_v6_strategy().boxed()
        } else {
            ip_v4_strategy().boxed()
        };
        via.prop_map(move |via| Route {
            to: to.clone(),
            via,
        })
    })
}

fn interface_strategy() -> impl Strategy<Value = Interface> {
    (
        iface_name_strategy(),
        proptest::strategy::Just(false),
        proptest::strategy::Just(false),
        proptest::collection::vec(cidr_strategy(), 0..=2),
        proptest::option::of(ip_v4_strategy()),
        proptest::option::of(ip_v6_strategy()),
        proptest::collection::vec(ip_strategy(), 0..=2),
        proptest::collection::vec(route_strategy(), 0..=2),
        proptest::strategy::Just(None),
        proptest::strategy::Just(None),
    )
        .prop_map(
            |(
                name,
                dhcp_v4,
                dhcp_v6,
                addresses,
                gateway_v4,
                gateway_v6,
                dns,
                routes,
                vlan,
                bridge,
            )| Interface {
                name,
                dhcp_v4,
                dhcp_v6,
                addresses,
                gateway_v4,
                gateway_v6,
                dns,
                routes,
                vlan,
                bridge,
            },
        )
}

fn model_strategy() -> impl Strategy<Value = Model> {
    // 0–3 interfaces with unique names; filter duplicates to keep valid.
    proptest::collection::vec(interface_strategy(), 0..=3).prop_map(|mut ifaces| {
        // Deduplicate by name, keep first occurrence.
        let mut seen = std::collections::BTreeSet::new();
        ifaces.retain(|i| seen.insert(i.name.clone()));
        // `to_model` collects interfaces through a `BTreeMap`, so the read
        // back order is by name; a valid model must match that order for
        // invariant 3 to hold on any backend.
        ifaces.sort_by(|a, b| a.name.cmp(&b.name));
        Model { interfaces: ifaces }
    })
}

