detent_core::module_conformance!(
    NetworkModule,
    fixtures = [
        SYSTEMD, NM, IFUPDOWN, NETPLAN, CRLF, NO_NEWLINE, TABS, UNKNOWN
    ],
    model_strategy = model_strategy(),
    injection_probes = [
        name_probe("a\nb"),
        name_probe("a\rb"),
        name_probe("a\0b"),
        address_probe("a\nb"),
        address_probe("a\0b"),
        dns_probe("a\nb"),
        gateway_probe("a\nb"),
        route_to_probe("a\nb"),
        vlan_link_probe("a\nb"),
        // Characters the upstream syntaxes treat as syntax: `;` and `$()`
        // (shell, via ifupdown's `up` lines), whitespace (argv splitting),
        // `#` (comments), `"` and `[`/`]` (YAML flow and INI headers), `=`.
        route_to_probe("0.0.0.0/0; reboot"),
        route_to_probe("$(reboot)"),
        route_to_probe("10.0.0.0/24 dev eth1"),
        route_to_probe("10.0.0.0/24#x"),
        route_to_probe("\"10.0.0.0/24\""),
        route_to_probe("[10.0.0.0/24]"),
        route_to_probe("to=10.0.0.0/24"),
        route_via_probe("192.168.1.1; reboot"),
        route_via_probe("192.168.1.1 dev eth1"),
        route_via_probe("192.168.1.1#x"),
        route_via_probe("\"192.168.1.1\""),
        route_via_probe("[192.168.1.1]"),
        route_via_probe("via=192.168.1.1"),
        address_probe("192.168.1.10/24 # x"),
        address_probe("[192.168.1.10/24]"),
        dns_probe("8.8.8.8, 1.1.1.1"),
        dns_probe("8.8.8.8 1.1.1.1"),
        gateway_probe("192.168.1.1; reboot"),
        name_probe("eth0:"),
        name_probe("#eth0"),
        vlan_link_probe("eth0 eth1"),
    ],
);

/// Every fixture must render back byte for byte.
#[test]
fn fixtures_round_trip_losslessly() {
    for fixture in [
        SYSTEMD, NM, IFUPDOWN, NETPLAN, CRLF, NO_NEWLINE, TABS, UNKNOWN,
    ] {
        let doc = NetworkModule::parse(fixture);
        assert_eq!(
            doc.as_ref().map(NetworkModule::render).ok(),
            Some(fixture.to_owned())
        );
    }
}

/// Parses `src` into a model, or an empty model if parsing somehow failed.
fn model_of(src: &str) -> Model {
    NetworkModule::parse(src)
        .ok()
        .and_then(|doc| NetworkModule::to_model(&doc).ok())
        .unwrap_or_default()
}

#[test]
fn systemd_fixture_parses_to_its_interfaces() {
    let model = model_of(SYSTEMD);
    // SYSTEMD has eth0 with DHCP + static address + DNS + route + VLAN
    assert_eq!(model.interfaces.len(), 1);
    let iface = &model.interfaces[0];
    assert_eq!(iface.name, "eth0");
    assert!(iface.dhcp_v4 || iface.dhcp_v6);
    assert!(iface.addresses.iter().any(|a| a == "192.168.1.10/24"));
    assert!(iface.dns.iter().any(|d| d == "192.168.1.1"));
    assert!(!iface.routes.is_empty());
    assert!(iface.vlan.is_some());
}

#[test]
fn nm_fixture_parses_to_its_interfaces() {
    let model = model_of(NM);
    assert_eq!(model.interfaces.len(), 1);
    let iface = &model.interfaces[0];
    assert_eq!(iface.name, "eth0");
    assert!(iface.addresses.iter().any(|a| a == "192.168.1.10/24"));
    assert!(iface.gateway_v4.is_some());
}

#[test]
fn ifupdown_fixture_parses_to_its_interfaces() {
    let model = model_of(IFUPDOWN);
    // lo + eth0
    assert!(model.interfaces.len() >= 1);
    assert!(model.interfaces.iter().any(|i| i.name == "eth0"));
    let eth0 = model.interfaces.iter().find(|i| i.name == "eth0").unwrap();
    assert!(eth0.addresses.iter().any(|a| a == "192.168.1.10/24"));
}

#[test]
fn netplan_fixture_parses_to_its_interfaces() {
    let model = model_of(NETPLAN);
    assert_eq!(model.interfaces.len(), 1);
    let iface = &model.interfaces[0];
    assert_eq!(iface.name, "eth0");
    assert!(iface.addresses.iter().any(|a| a == "192.168.1.10/24"));
    assert_eq!(iface.gateway_v4.as_deref(), Some("192.168.1.1"));
    assert!(!iface.routes.is_empty());
}

#[test]
fn crlf_fixture_parses_without_its_terminators() {
    let model = model_of(CRLF);
    assert_eq!(model.interfaces.len(), 1);
    assert_eq!(model.interfaces[0].name, "eth0");
}

#[test]
fn a_missing_trailing_newline_survives() {
    let model = model_of(NO_NEWLINE);
    assert_eq!(model.interfaces.len(), 1);
    // Round-trip must preserve missing newline.
    let doc = NetworkModule::parse(NO_NEWLINE).unwrap();
    assert_eq!(NetworkModule::render(&doc), NO_NEWLINE);
    assert_eq!(model.interfaces[0].name, "eth0");
}

#[test]
fn tabs_fixture_keeps_the_value_without_its_spacing() {
    let model = model_of(TABS);
    assert_eq!(model.interfaces[0].name, "eth0");
    assert!(
        model.interfaces[0]
            .addresses
            .iter()
            .any(|a| a == "192.168.1.10/24")
    );
}

#[test]
fn unknown_directives_are_not_modeled_but_survive() {
    let model = model_of(UNKNOWN);
    // Unknown sections/keys must not appear as interfaces beyond eth0.
    assert!(model.interfaces.iter().any(|i| i.name == "eth0"));
    // No spurious interface from UnknownSection.
    assert!(!model.interfaces.iter().any(|i| i.name == "UnknownSection"));
    // But the file must still round-trip losslessly (checked above); test that unknown lines exist in render.
    let doc = NetworkModule::parse(UNKNOWN).unwrap();
    let rendered = NetworkModule::render(&doc);
    assert!(rendered.contains("UnknownSection"));
    assert!(rendered.contains("UnknownKey"));
}

/// Static routes traverse the same parse/model/validate/apply/render path as
/// every backend that represents them. NetworkManager is intentionally absent:
/// its modeled keyfile subset has no route representation.
#[test]
fn route_models_validate_and_round_trip_through_real_backends() -> Result<(), String> {
    let sources = [
        "[Match]\nName=eth0\n\n[Route]\nDestination=10.0.0.0/24\nGateway=192.168.1.254\n",
        "auto eth0\niface eth0 inet static\n\tup ip route add 10.0.0.0/24 via 192.168.1.254\n",
        "network:\n  version: 2\n  ethernets:\n    eth0:\n      routes:\n        - to: 10.0.0.0/24\n          via: 192.168.1.254\n",
    ];
    let profile = HostProfile::default_for_tests();
    for source in sources {
        let mut doc = NetworkModule::parse(source).map_err(|e| e.to_string())?;
        let model = NetworkModule::to_model(&doc).map_err(|e| e.to_string())?;
        let route = model
            .interfaces
            .iter()
            .find_map(|iface| iface.routes.first())
            .ok_or_else(|| format!("route missing from parsed model: {model:?}"))?;
        assert_eq!(route.to, "10.0.0.0/24");
        assert_eq!(route.via, "192.168.1.254");
        assert!(!NetworkModule::validate(&model, &ValidationCtx::new(&profile)).has_errors());
        NetworkModule::apply(&mut doc, &model).map_err(|e| e.to_string())?;
        let reparsed =
            NetworkModule::parse(&NetworkModule::render(&doc)).map_err(|e| e.to_string())?;
        assert_eq!(
            NetworkModule::to_model(&reparsed).map_err(|e| e.to_string())?,
            model
        );
    }
    Ok(())
}

#[test]
fn an_edited_value_reaches_the_rendered_file() -> Result<(), String> {
    let src = "[Match]\nName=eth0\n\n[Network]\nDHCP=yes\n";
    let mut doc = NetworkModule::parse(src).map_err(|e| e.to_string())?;
    let mut model = NetworkModule::to_model(&doc).map_err(|e| e.to_string())?;
    model.interfaces[0].addresses = vec!["10.0.0.5/24".to_owned()];
    model.interfaces[0].dhcp_v4 = false;
    let report = NetworkModule::apply(&mut doc, &model).map_err(|e| e.to_string())?;
    assert!(report.added > 0 || report.changed_lines > 0);
    let rendered = NetworkModule::render(&doc);
    assert!(rendered.contains("10.0.0.5/24"));
    // Unknowns survive: add a comment and ensure edit keeps it.
    let src2 = "# keep me\n[Match]\nName=eth0\n\n[Network]\nDHCP=yes\n";
    let mut doc2 = NetworkModule::parse(src2).map_err(|e| e.to_string())?;
    let mut model2 = NetworkModule::to_model(&doc2).map_err(|e| e.to_string())?;
    model2.interfaces[0].addresses = vec!["10.0.0.5/24".to_owned()];
    model2.interfaces[0].dhcp_v4 = false;
    NetworkModule::apply(&mut doc2, &model2).map_err(|e| e.to_string())?;
    assert!(NetworkModule::render(&doc2).contains("# keep me"));
    Ok(())
}

/// The section header in force at the line that holds `needle`: the last
/// `[...]` line above it.
fn section_above(rendered: &str, needle: &str) -> Option<String> {
    let mut current = None;
    for line in rendered.lines() {
        if line.contains(needle) {
            return current;
        }
        if line.starts_with('[') {
            current = Some(line.to_owned());
        }
    }
    None
}

#[test]
fn edit_keeps_unknown_keys_under_their_section() -> Result<(), String> {
    // H16: `UnknownKey` is not modelled, so it stays where it is. The edit adds
    // a `[Route]` section; that section must not land between `[Network]` and
    // `UnknownKey`, or networkd reads `UnknownKey` as a route key.
    let src = "[Match]\nName=eth0\n\n[UnknownSection]\nFoo=bar\n\n[Network]\nDHCP=yes\nUnknownKey=value\n\n[DHCP]\nRouteMetric=100\n";
    let mut doc = NetworkModule::parse(src).map_err(|e| e.to_string())?;
    let mut model = NetworkModule::to_model(&doc).map_err(|e| e.to_string())?;
    let iface = model
        .interfaces
        .iter_mut()
        .find(|i| i.name == "eth0")
        .ok_or("no eth0 in the model")?;
    iface.dhcp_v4 = false;
    iface.dhcp_v6 = false;
    iface.addresses = vec!["10.0.0.5/24".to_owned()];
    iface.routes = vec![detent_module_network::Route {
        to: "10.1.0.0/16".to_owned(),
        via: "10.0.0.1".to_owned(),
    }];
    NetworkModule::apply(&mut doc, &model).map_err(|e| e.to_string())?;
    let rendered = NetworkModule::render(&doc);
    assert_eq!(
        section_above(&rendered, "UnknownKey").as_deref(),
        Some("[Network]"),
        "{rendered:?}"
    );
    assert_eq!(
        section_above(&rendered, "Foo=bar").as_deref(),
        Some("[UnknownSection]"),
        "{rendered:?}"
    );
    assert_eq!(
        section_above(&rendered, "RouteMetric").as_deref(),
        Some("[DHCP]"),
        "{rendered:?}"
    );
    let back = NetworkModule::to_model(&doc).map_err(|e| e.to_string())?;
    assert_eq!(back, model);
    Ok(())
}
